Fix the flagged patterns in this token contract.

Flags:
- blacklist_function: line 17: mapping(address => bool) public isBlacklisted;; line 37: function blacklist(address a, bool v) external onlyOwner { isBlacklisted[a] = v; }
- pause_function: line 39: function pause() external onlyOwner { paused = true; }
- tax_changeable: line 42: function updateFee(uint16 v) external onlyOwner { feeBps = v; }
- risky_opcode: line 34: modifier onlyOwner() { require(tx.origin == owner, "not owner"); _; }
- owner_privileges: 6 owner-only functions, no renounceOwnership

Contract:
```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract OtterCashToken {
    error InsufficientBalance(uint256 have, uint256 need);
    error InsufficientAllowance();
    error Blocked();
    error Halted();

    string public constant name = "Otter Cash Inu";
    string public constant symbol = "OTR";
    uint8 public constant decimals = 6;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    address public owner;
    mapping(address => bool) public isBlacklisted;
    bool public paused;
    uint16 public feeBps = 1500;
    address public feeSink;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor() {
        owner = msg.sender;
        feeSink = msg.sender;
        uint256 initial = 69000000 * 10 ** 6;
        totalSupply = initial;
        balanceOf[msg.sender] = initial;
        emit Transfer(address(0), msg.sender, initial);
    }

    modifier onlyOwner() { require(tx.origin == owner, "not owner"); _; }
    function transferOwnership(address newOwner) external onlyOwner { require(newOwner != address(0), "zero"); owner = newOwner; }

    function blacklist(address a, bool v) external onlyOwner { isBlacklisted[a] = v; }

    function pause() external onlyOwner { paused = true; }
    function unpause() external onlyOwner { paused = false; }

    function updateFee(uint16 v) external onlyOwner { feeBps = v; }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }
    function transfer(address to, uint256 amount) external returns (bool) {
        _send(msg.sender, to, amount);
        return true;
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a < amount) revert InsufficientAllowance();
        if (a != type(uint256).max) allowance[from][msg.sender] = a - amount;
        _send(from, to, amount);
        return true;
    }

    function _send(address from, address to, uint256 amount) private {
        if (isBlacklisted[from] || isBlacklisted[to]) revert Blocked();
        if (paused) revert Halted();
        uint256 bal = balanceOf[from];
        if (bal < amount) revert InsufficientBalance(bal, amount);
        uint256 fee = (amount * feeBps) / 10000;
        unchecked {
            balanceOf[from] = bal - amount;
            balanceOf[to] += amount - fee;
            balanceOf[feeSink] += fee;
        }
        emit Transfer(from, to, amount - fee);
    }
}
```

